// Backend purpose: Generates development-only sample records for PatientFaker.
using Bogus;
using BookingSystem.Domain.Entities;

namespace BookingSystem.Infrastructure.Fakers
{
    public class PatientFaker
    {
        public Faker<Patient> GeneratePatient()
        {
            var faker = new Faker<Patient>()
                //.RuleFor(p => p.PatientId, f => f.IndexFaker) // PatientId is generated by the database, not by Bogus.
                .RuleFor(p => p.FullName, f => f.Name.FullName()) // Generate a realistic patient name.
                .RuleFor(p => p.SocialSecurityNumber, (f, p) => f.Random.Int(100000000, 999999999).ToString())
                .RuleFor(p => p.Bookings, f => new List<Booking>()); // Start with an empty booking collection.

            return faker;
        }
    }
}
